async def act(page):
    """
    From the current 'New Rule' page, reveal the Actions section, select all customer groups
    so the rule applies to all customers, set Apply to a percent discount, set Discount Amount to 20,
    and save the rule. Save is the last action because it may navigate away.
    """
    # There are no applicable knowledge-base helper functions for interacting with this Magento UI,
    # so we use Playwright page APIs directly.

    # 1) Open the Actions tab/section to reveal the Actions controls (does not navigate away).
    try:
        await page.get_by_role("link", name="Actions").click()
    except Exception:
        # Fallback to non-exact match if labeling differs slightly
        try:
            await page.get_by_role("link", name="Actions", exact=False).click()
        except Exception:
            # If the click fails, continue — the Actions panel may already be visible.
            pass

    # Allow UI to render the Actions panel
    await page.wait_for_timeout(500)

    # 2) Ensure all Customer Groups are selected so rule applies to all customers.
    customer_labels = [
        "NOT LOGGED IN",
        "General",
        "Wholesale",
        "VIP Member",
        "Private Sales Member",
    ]
    try:
        await page.get_by_role("listbox", name="Customer Groups *").select_option(
            [{"label": lbl} for lbl in customer_labels]
        )
    except Exception:
        # Fallback: try non-exact name
        try:
            await page.get_by_role("listbox", name="Customer Groups", exact=False).select_option(
                [{"label": lbl} for lbl in customer_labels]
            )
        except Exception:
            # Last resort: try clicking each option element inside the listbox
            try:
                cg_list = page.get_by_role("listbox", name="Customer Groups *")
                opts = cg_list.get_by_role("option")
                count = await opts.count()
                for i in range(count):
                    opt = opts.nth(i)
                    try:
                        await opt.click()
                    except Exception:
                        pass
            except Exception:
                # If unable to select customer groups, continue — Saving will still proceed.
                pass

    # 3) Set Apply to a percent discount. Try common labels and a likely internal value.
    apply_candidates = [
        {"label": "Percent of product price discount"},
        {"label": "Percent of product price"},
        {"value": "by_percent"},
    ]
    applied = False
    for candidate in apply_candidates:
        if applied:
            break
        try:
            await page.get_by_role("combobox", name="Apply").select_option(candidate)
            applied = True
            break
        except Exception:
            try:
                await page.get_by_role("combobox", name="Apply", exact=False).select_option(candidate)
                applied = True
                break
            except Exception:
                continue

    # 4) Fill Discount Amount with 20
    try:
        await page.get_by_role("textbox", name="Discount Amount").fill("20")
    except Exception:
        try:
            await page.get_by_role("textbox", name="Discount").fill("20")
        except Exception:
            try:
                await page.get_by_role("textbox", name="Discount Amount", exact=False).fill("20")
            except Exception:
                # If unable to find the textbox, raise so caller can detect failure
                raise

    # Brief pause to ensure UI updates
    await page.wait_for_timeout(300)

    # 5) Save the rule (final action; may navigate away)
    try:
        await page.get_by_role("button", name="Save").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        try:
            await page.get_by_role("button", name="Save and Continue Edit").click()
            await page.wait_for_load_state("networkidle")
        except Exception:
            # Surface the error to the caller
            raise

